insert into public.sd_specialties (slug, name, summary, description, reasons, icon, image_url, image_small_url, image_alt, image_width, image_height, sort_order) values ('general-medicine', 'General medicine', 'Everyday health concerns, check-ups and ongoing care.', 'General medicine is usually the first stop for new symptoms, routine check-ups and long-term conditions. A general physician can assess you, arrange tests and refer you to a specialist when needed.', array['Fever, cough or a new symptom', 'Routine health check-ups', 'Managing a long-term condition', 'Help deciding which specialist to see']::text[], 'Stethoscope', '/images/specialties/specialty-general-medicine.webp', '/images/specialties/specialty-general-medicine-sm.webp', 'A general physician at a desk with a stethoscope and notes', 1200, 900, 1) on conflict (slug) do nothing;
insert into public.sd_specialties (slug, name, summary, description, reasons, icon, image_url, image_small_url, image_alt, image_width, image_height, sort_order) values ('cardiology', 'Cardiology', 'Heart and blood vessel health.', 'Cardiology looks after the heart and circulation. Visits often include a conversation about symptoms and history, and tests such as an ECG when the doctor recommends them.', array['Chest discomfort or palpitations', 'High blood pressure follow-up', 'Breathlessness on exertion', 'Family history of heart conditions']::text[], 'HeartPulse', '/images/specialties/specialty-cardiology.webp', '/images/specialties/specialty-cardiology-sm.webp', 'An illustrated heart next to a heart-rhythm monitor', 1200, 900, 2) on conflict (slug) do nothing;
insert into public.sd_specialties (slug, name, summary, description, reasons, icon, image_url, image_small_url, image_alt, image_width, image_height, sort_order) values ('orthopaedics', 'Orthopaedics', 'Bones, joints, muscles and sports injuries.', 'Orthopaedics covers the bones, joints, ligaments and muscles that keep you moving, from sprains and fractures to long-standing joint pain.', array['Joint or back pain', 'Sports and exercise injuries', 'Stiffness that limits movement', 'Follow-up after a fracture']::text[], 'Bone', '/images/specialties/specialty-orthopaedics.webp', '/images/specialties/specialty-orthopaedics-sm.webp', 'A knee X-ray on a lightbox beside a joint model and crutch', 1200, 900, 3) on conflict (slug) do nothing;
insert into public.sd_specialties (slug, name, summary, description, reasons, icon, image_url, image_small_url, image_alt, image_width, image_height, sort_order) values ('dermatology', 'Dermatology', 'Skin, hair and nail conditions.', 'Dermatology deals with the skin, hair and nails. A dermatologist can examine changes in your skin and talk you through suitable next steps.', array['Rashes, itching or irritation', 'Changes in a mole or spot', 'Acne or persistent breakouts', 'Hair or nail concerns']::text[], 'ScanFace', '/images/specialties/specialty-dermatology.webp', '/images/specialties/specialty-dermatology-sm.webp', 'Layers of skin under a magnifying glass', 1200, 900, 4) on conflict (slug) do nothing;
insert into public.sd_specialties (slug, name, summary, description, reasons, icon, image_url, image_small_url, image_alt, image_width, image_height, sort_order) values ('paediatrics', 'Paediatrics', 'Care for babies, children and teenagers.', 'Paediatrics focuses on the health and development of children, from newborn check-ups through to adolescence.', array['Growth and development checks', 'Childhood illnesses', 'Vaccination questions', 'Advice for parents and carers']::text[], 'Baby', '/images/specialties/specialty-paediatrics.webp', '/images/specialties/specialty-paediatrics-sm.webp', 'A child beside a height chart, a teddy bear and toy blocks', 1200, 900, 5) on conflict (slug) do nothing;
insert into public.sd_specialties (slug, name, summary, description, reasons, icon, image_url, image_small_url, image_alt, image_width, image_height, sort_order) values ('neurology', 'Neurology', 'The brain, spine and nervous system.', 'Neurology covers conditions of the brain, spinal cord and nerves. Appointments usually start with a detailed history and examination.', array['Frequent or severe headaches', 'Numbness or tingling', 'Dizziness or balance problems', 'Memory or concentration concerns']::text[], 'Brain', '/images/specialties/specialty-neurology.webp', '/images/specialties/specialty-neurology-sm.webp', 'An illustrated brain with connected nerve pathways', 1200, 900, 6) on conflict (slug) do nothing;
insert into public.sd_specialties (slug, name, summary, description, reasons, icon, image_url, image_small_url, image_alt, image_width, image_height, sort_order) values ('ophthalmology', 'Ophthalmology', 'Eye health and vision.', 'Ophthalmology looks after the eyes and vision, from routine eye checks to conditions that need a specialist’s attention.', array['Blurred or changing vision', 'Red, painful or dry eyes', 'Routine eye examinations', 'Advice on glasses or lenses']::text[], 'Eye', '/images/specialties/specialty-ophthalmology.webp', '/images/specialties/specialty-ophthalmology-sm.webp', 'An eye-test chart, an illustrated eye and glasses', 1200, 900, 7) on conflict (slug) do nothing;
insert into public.sd_specialties (slug, name, summary, description, reasons, icon, image_url, image_small_url, image_alt, image_width, image_height, sort_order) values ('dentistry', 'Dentistry', 'Teeth, gums and oral health.', 'Dentistry covers check-ups, cleaning and treatment for the teeth and gums, as well as advice on keeping your mouth healthy.', array['Toothache or sensitivity', 'Routine check-ups and cleaning', 'Bleeding or sore gums', 'Advice on dental care']::text[], 'Smile', '/images/specialties/specialty-dentistry.webp', '/images/specialties/specialty-dentistry-sm.webp', 'A tooth model with a toothbrush and dental mirror', 1200, 900, 8) on conflict (slug) do nothing;
insert into public.sd_specialties (slug, name, summary, description, reasons, icon, image_url, image_small_url, image_alt, image_width, image_height, sort_order) values ('gynaecology', 'Gynaecology', 'Women’s health at every stage of life.', 'Gynaecology focuses on women’s reproductive health, including routine screening, menstrual concerns and advice through different life stages.', array['Period-related concerns', 'Routine screening', 'Questions about contraception', 'Menopause support']::text[], 'Flower2', '/images/specialties/specialty-gynaecology.webp', '/images/specialties/specialty-gynaecology-sm.webp', 'A doctor beside an ultrasound unit in a women’s health clinic', 1200, 900, 9) on conflict (slug) do nothing;
insert into public.sd_specialties (slug, name, summary, description, reasons, icon, image_url, image_small_url, image_alt, image_width, image_height, sort_order) values ('diagnostics', 'Diagnostics and laboratory', 'Tests that help your doctor understand what’s going on.', 'Diagnostic and laboratory services carry out the tests your doctor requests, such as blood tests and imaging, and share the results with your care team.', array['Blood and urine tests', 'Tests requested by your doctor', 'Routine screening panels', 'Imaging appointments']::text[], 'Microscope', '/images/specialties/specialty-diagnostics.webp', '/images/specialties/specialty-diagnostics-sm.webp', 'Laboratory equipment: a microscope, sample tubes and petri dishes', 1200, 900, 10) on conflict (slug) do nothing;
