insert into public.sd_products (slug, sku, name, category_id, price, stock, low_stock_threshold, summary, description, features, in_the_box, featured, published, is_demo, sort_order) values ('adjustable-walking-stick', 'SD-MOB-001', 'Adjustable Walking Stick', (select id from public.sd_categories where slug = 'mobility'), 899, 20, 5, 'Height-adjustable with a comfortable grip.', 'A lightweight aluminium walking stick with height adjustment, an ergonomic handle, wrist strap and non-slip rubber tip.', array['Adjustable height', 'Ergonomic handle', 'Wrist strap', 'Non-slip rubber tip']::text[], array['Walking stick', 'Instructions']::text[], false, true, true, 11) on conflict (slug) do nothing;
