insert into public.sd_nav_links (location, label, href, sort_order) select v.location, v.label, v.href, v.sort_order from (values ('header', 'Specialties', '/specialties', 1), ('header', 'Doctors', '/doctors', 2), ('header', 'Facilities', '/facilities', 3), ('header', 'Store', '/store', 4), ('header', 'Contact', '/contact', 5), ('footer_explore', 'Find a doctor', '/doctors', 6), ('footer_explore', 'Book an appointment', '/appointment', 7), ('footer_explore', 'Facilities', '/facilities', 8), ('footer_explore', 'Health essentials', '/store', 9), ('footer_explore', 'Contact us', '/contact', 10)) as v(location, label, href, sort_order) where not exists (select 1 from public.sd_nav_links);
insert into public.sd_page_sections (key, heading, body, image_url, image_small_url, cta_label, cta_href, cta2_label, cta2_href, items, sort_order) values ('home.hero', 'Healthcare that puts you first', 'Explore healthcare services, discover medical professionals, request appointments, and browse healthcare essentials in one convenient digital experience.', '/images/hero/medinova-hero-healthcare-team.webp', '/images/hero/medinova-hero-healthcare-team-sm.webp', 'Book an appointment', '/appointment', 'Explore services', '/specialties', '[]'::jsonb, 1) on conflict (key) do nothing;
insert into public.sd_page_sections (key, heading, body, image_url, image_small_url, cta_label, cta_href, cta2_label, cta2_href, items, sort_order) values ('home.specialties', 'Find the right specialty', 'Start with what you need help with. Each specialty page explains what to expect and who you can see.', null, null, null, null, null, null, '[]'::jsonb, 2) on conflict (key) do nothing;
insert into public.sd_page_sections (key, heading, body, image_url, image_small_url, cta_label, cta_href, cta2_label, cta2_href, items, sort_order) values ('home.appointment', 'Request an appointment in three steps', '', '/images/hero/doctor-patient-consultation.webp', '/images/hero/doctor-patient-consultation-sm.webp', 'Book an appointment', '/appointment', null, null, '["Choose a specialty, and a doctor if you have one in mind.","Pick a day and a time of day that suits you.","The team calls you back to confirm a slot."]'::jsonb, 3) on conflict (key) do nothing;
insert into public.sd_page_sections (key, heading, body, image_url, image_small_url, cta_label, cta_href, cta2_label, cta2_href, items, sort_order) values ('home.team', 'Meet the care team', 'Browse profiles by specialty, language and the days each person is available.', null, null, null, null, null, null, '[]'::jsonb, 4) on conflict (key) do nothing;
