insert into public.sd_page_sections (key, heading, body, image_url, image_small_url, cta_label, cta_href, cta2_label, cta2_href, items, sort_order) values ('home.why', 'Why people choose SaraDev', 'Everything you need before, between and after visits, in one place.', '/images/hero/hospital-reception-welcome.webp', '/images/hero/hospital-reception-welcome-sm.webp', null, null, null, null, '[{"icon":"Search","title":"Find the right care","body":"Browse specialties and team profiles, and filter by language and availability."},{"icon":"CalendarCheck","title":"Request a time that suits you","body":"Send an appointment request in a few steps, without waiting on hold."},{"icon":"MessageCircle","title":"Talk to us on WhatsApp","body":"Every page offers a one-tap message with your question already written."},{"icon":"ShoppingBag","title":"Order everyday essentials","body":"Pick up home-care items from the same place you manage your visits."}]'::jsonb, 6) on conflict (key) do nothing;
